This is a miscompilation bug in SLPVectorizer.
Issue title: [SLP] Miscompilation when vectorizing boolean selects with poison
Detailed information:
BUG TYPE:
    miscompilation

VERIFICATION RESULT:
    Invalid refinement in @test_explicit_poison_leaves -- Target is more poisonous than source

VIOLATED PROPERTY:
    poison refinement

SOURCE (pre-transformation IR):
define i1 @test_explicit_poison_leaves(i1 %a, i1 %b) {
  %op1 = select i1 %a, i1 true, i1 poison
  %op2 = select i1 %b, i1 true, i1 poison
  %res = select i1 %op1, i1 true, i1 %op2
  ret i1 %res
}

TARGET (post-transformation IR):
; ModuleID = '<stdin>'
source_filename = "<stdin>"

define i1 @test_explicit_poison_leaves(i1 %a, i1 %b) {
  %op.rdx = select i1 %a, i1 true, i1 poison
  %op.rdx1 = select i1 %b, i1 true, i1 %op.rdx
  ret i1 %op.rdx1
}

WHAT THE TRANSFORMATION CHANGED:
  only in target:
    %op.rdx: %op.rdx = select i1 %a, i1 true, i1 poison
    %op.rdx1: %op.rdx1 = select i1 %b, i1 true, i1 %op.rdx
  only in source:
    %op1: %op1 = select i1 %a, i1 true, i1 poison
    %op2: %op2 = select i1 %b, i1 true, i1 poison
    %res: %res = select i1 %op1, i1 true, i1 %op2

CRITICAL VALUES:
    %op.rdx
    %op.rdx1
    %op1
    %op2
    %res

DEPENDENCY CHAIN (source):
    %op1 = select i1 %a, i1 true, i1 poison
    %op2 = select i1 %b, i1 true, i1 poison
    %res = select i1 %op1, i1 true, i1 %op2

CONTROL FLOW (blocks entered by the failing execution):
    (none)

COUNTEREXAMPLE INPUT:
    i1 %a = #x1 (1)
    i1 %b = poison

DIVERGENCE (source vs target on that input):
    %op.rdx: source = (not computed)   target = #x1 (1)
    %op.rdx1: source = (not computed)   target = poison

INTERPRETATION:
    A transformation may only make a program *less* poisonous. Wherever the source produces a well-defined value, the target must produce the same value -- it may not produce poison.
    On the input above the source yields #x1 (1) while the target yields poison.
    The earliest reported divergence is at %op.rdx.

Please modify the following code in llvm/lib/Transforms/Vectorize/SLPVectorizer.cpp to fix the bug:
```cpp
    if (!VectorizedTree) {
      if (!CheckForReusedReductionOps) {
        for (ReductionOpsType &RdxOps : ReductionOps)
          for (Value *RdxOp : RdxOps)
            V.analyzedReductionRoot(cast<Instruction>(RdxOp));
      }
      return nullptr;
    }

    // Reorder operands of bool logical op in the natural order to avoid
    // possible problem with poison propagation. If not possible to reorder
    // (both operands are originally RHS), emit an extra freeze instruction
    // for the LHS operand.
    // I.e., if we have original code like this:
    // RedOp1 = select i1 ?, i1 LHS, i1 false
    // RedOp2 = select i1 RHS, i1 ?, i1 false

    // Then, we swap LHS/RHS to create a new op that matches the poison
    // semantics of the original code.

    // If we have original code like this and both values could be poison:
    // RedOp1 = select i1 ?, i1 LHS, i1 false
    // RedOp2 = select i1 ?, i1 RHS, i1 false

    // Then, we must freeze LHS in the new op.
    auto FixBoolLogicalOps =
        [&, VectorizedTree](Value *&LHS, Value *&RHS, Instruction *RedOp1,
                            Instruction *RedOp2, bool InitStep) {
          if (!AnyBoolLogicOp)
            return;
          if (isBoolLogicOp(RedOp1) && ((!InitStep && LHS == VectorizedTree) ||
                                        getRdxOperand(RedOp1, 0) == LHS ||
                                        isGuaranteedNotToBePoison(LHS, AC)))
            return;
          if (isBoolLogicOp(RedOp2) && ((!InitStep && RHS == VectorizedTree) ||
                                        getRdxOperand(RedOp2, 0) == RHS ||
                                        isGuaranteedNotToBePoison(RHS, AC))) {
            std::swap(LHS, RHS);
            return;
          }
          if (LHS != VectorizedTree)
            LHS = Builder.CreateFreeze(LHS);
        };
    // Finish the reduction.
    // Need to add extra arguments and not vectorized possible reduction values.
    // Try to avoid dependencies between the scalar remainders after reductions.
    auto FinalGen = [&](ArrayRef<std::pair<Instruction *, Value *>> InstVals,
                        bool InitStep) {
      unsigned Sz = InstVals.size();
      SmallVector<std::pair<Instruction *, Value *>> ExtraReds(Sz / 2 + Sz % 2);
      for (unsigned I = 0, E = (Sz / 2) * 2; I < E; I += 2) {
        Instruction *RedOp = InstVals[I + 1].first;
        Builder.SetCurrentDebugLocation(RedOp->getDebugLoc());
        Value *RdxVal1 = InstVals[I].second;
        Value *StableRdxVal1 = RdxVal1;
        auto It1 = TrackedVals.find(RdxVal1);
        if (It1 != TrackedVals.end())
          StableRdxVal1 = It1->second;
        Value *RdxVal2 = InstVals[I + 1].second;
        Value *StableRdxVal2 = RdxVal2;
        auto It2 = TrackedVals.find(RdxVal2);
        if (It2 != TrackedVals.end())
          StableRdxVal2 = It2->second;
        // To prevent poison from leaking across what used to be sequential,
        // safe, scalar boolean logic operations, the reduction operand must be
        // frozen.
        FixBoolLogicalOps(StableRdxVal1, StableRdxVal2, InstVals[I].first,
                          RedOp, InitStep);
        Value *ExtraRed = createOp(Builder, RdxKind, StableRdxVal1,
                                   StableRdxVal2, "op.rdx", ReductionOps);
        ExtraReds[I / 2] = std::make_pair(InstVals[I].first, ExtraRed);
      }
      if (Sz % 2 == 1)
        ExtraReds[Sz / 2] = InstVals.back();
      return ExtraReds;
    };
```

